oxy_webhelp_navlinks = {"aws_workloads_protection_setup-d39536e17688":{"topics":[{"title":"SLA Domain assignment hierarchy for AWS","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides hierarchy-based, automatic protection for AWS workloads,         simplifying the assignment of protection across various levels, such as AWS accounts and         individual workloads.<\/p>","href":"saas\/aws_hierarchy_sla_assignment.html","attributes":{"data-id":"aws_hierarchy_sla_assignment"},"menu":{"hasChildren":false},"tocID":"aws_hierarchy_sla_assignment-d39536e17699","topics":[]},{"title":"Best practices for AWS SLA Domain assignment","shortdesc":"<p class=\"shortdesc\">Information about the best practices for assigning SLA Domains to AWS workloads,         ensuring effective data protection and compliance.<\/p>","href":"saas\/aws_best_practices_sla_assignment.html","attributes":{"data-id":"aws_best_practices_sla_assignment"},"menu":{"hasChildren":false},"tocID":"aws_best_practices_sla_assignment-d39536e17712","topics":[]},{"title":"Evaluate AWS SLA Domain options","shortdesc":"<p class=\"shortdesc\">Understanding the various protection options is important when creating an SLA Domain         for your AWS workloads. This ensures alignment with organizational needs. Thoroughly         evaluating these options enables informed decisions and provides effective protection for         the workloads.<\/p>","href":"saas\/aws_evaluate_sla_option.html","attributes":{"data-id":"aws_evaluate_sla_option"},"menu":{"hasChildren":false},"tocID":"aws_evaluate_sla_option-d39536e17723","next":"aws_evaluate_sla_option-d39536e17723"},{"title":"SLA Domains for <span class=\"ph\">RSC<\/span>-managed AWS accounts","shortdesc":"<p class=\"shortdesc\">SLA Domains for <span class=\"ph\">RSC<\/span>-managed accounts archive to Rubrik Cloud Vault by         default and do not support replication.<\/p>","href":"saas\/aws_hosted_sla_domains.html","attributes":{"data-id":"aws_hosted_sla_domains"},"menu":{"hasChildren":false},"tocID":"aws_hosted_sla_domains-d39536e17947","topics":[]},{"title":"Region level SLA Domain assignment for AWS","shortdesc":"<p class=\"shortdesc\">You can apply a unified policy to an entire AWS region with a region-level SLA Domain         assignment, ensuring any new resource in that region is automatically protected.<\/p>","href":"saas\/aws_region_level_sla_domain_assignment.html","attributes":{"data-id":"aws_region_level_sla_domain_assignment"},"menu":{"hasChildren":false},"tocID":"aws_region_level_sla_domain_assignment-d39536e17964","topics":[]},{"title":"Configure AWS protection","shortdesc":"<p class=\"shortdesc\">After you have decided on the protection policies you want to configure, you can         begin configuration by creating an SLA Domain and assigning protection to AWS workloads and         AWS accounts.<\/p>","href":"saas\/aws_protection_config.html","attributes":{"data-id":"aws_protection_config"},"menu":{"hasChildren":false},"tocID":"aws_protection_config-d39536e17975","next":"aws_protection_config-d39536e17975"},{"title":"AWS protection limitations","shortdesc":"<p class=\"shortdesc\">Information about <span class=\"ph\">RSC<\/span> limitations for AWS protection and         recovery.<\/p>","href":"saas\/aws_protection_limitations.html","attributes":{"data-id":"aws_protection_limitations"},"menu":{"hasChildren":false},"tocID":"aws_protection_limitations-d39536e18310","topics":[]},{"title":"Amazon RDS protection removal","shortdesc":"<p class=\"shortdesc\">When you remove an SLA Domain from an Amazon RDS database or a cloud account from <span class=\"ph\">RSC<\/span>, certain AWS resources and configurations persist. Review this behavior         before removing protection.<\/p>","href":"aws\/aws_rds_protection_removal.html","attributes":{"data-id":"aws_rds_protection_removal"},"menu":{"hasChildren":false},"tocID":"aws_rds_protection_removal-d39536e18324","topics":[]}]}};